    public static class GalleryShowCaseHeaderTokens
    {
        public static readonly ControlTokenIdentity Identity = new ControlTokenIdentity("AtomUI", "GalleryShowCaseHeader");
    }

    public class GalleryShowCaseHeaderTokenResourceExtension : TokenResourceExtension<GalleryShowCaseHeaderTokenKey>
    {
        public GalleryShowCaseHeaderTokenResourceExtension()
        {
        }

        public GalleryShowCaseHeaderTokenResourceExtension(GalleryShowCaseHeaderTokenKey kind)
            : base(kind)
        {
        }

        protected override object GetResourceKey(GalleryShowCaseHeaderTokenKey kind)
        {
            var slot = (int)kind;
            if (slot >= 0)
            {
                if ((uint)slot >= 255u)
                {
                    throw new global::System.ArgumentOutOfRangeException(nameof(kind));
                }
                return ControlTokenResourceKey.Global(GalleryShowCaseHeaderTokens.Identity, (SharedTokenKind)slot);
            }
            var ownSlot = -1 - slot;
            if ((uint)ownSlot < 19u)
            {
                return (GalleryShowCaseHeaderTokenKind)ownSlot;
            }
            throw new global::System.ArgumentOutOfRangeException(nameof(kind));
        }
    }

