    public static class GalleryWindowTitleBarTokens
    {
        public static readonly ControlTokenIdentity Identity = new ControlTokenIdentity("AtomUI", "GalleryWindowTitleBar");
    }

    public class GalleryWindowTitleBarTokenResourceExtension : TokenResourceExtension<GalleryWindowTitleBarTokenKey>
    {
        public GalleryWindowTitleBarTokenResourceExtension()
        {
        }

        public GalleryWindowTitleBarTokenResourceExtension(GalleryWindowTitleBarTokenKey kind)
            : base(kind)
        {
        }

        protected override object GetResourceKey(GalleryWindowTitleBarTokenKey kind)
        {
            var slot = (int)kind;
            if (slot >= 0)
            {
                if ((uint)slot >= 255u)
                {
                    throw new global::System.ArgumentOutOfRangeException(nameof(kind));
                }
                return ControlTokenResourceKey.Global(GalleryWindowTitleBarTokens.Identity, (SharedTokenKind)slot);
            }
            var ownSlot = -1 - slot;
            if ((uint)ownSlot < 2u)
            {
                return (GalleryWindowTitleBarTokenKind)ownSlot;
            }
            throw new global::System.ArgumentOutOfRangeException(nameof(kind));
        }
    }

