    public class SemanticPartPreviewTokenResourceExtension : TokenResourceExtension<SemanticPartPreviewTokenKey>
    {
        public SemanticPartPreviewTokenResourceExtension()
        {
        }

        public SemanticPartPreviewTokenResourceExtension(SemanticPartPreviewTokenKey kind)
            : base(kind)
        {
        }

        protected override object GetResourceKey(SemanticPartPreviewTokenKey kind)
        {
            var slot = (int)kind;
            if (slot >= 0)
            {
                if ((uint)slot >= 255u)
                {
                    throw new global::System.ArgumentOutOfRangeException(nameof(kind));
                }
                return ControlTokenResourceKey.Global(SemanticPartPreviewTokens.Identity, (SharedTokenKind)slot);
            }
            var ownSlot = -1 - slot;
            throw new global::System.ArgumentOutOfRangeException(nameof(kind));
        }
    }

