    public static class ShowCaseZoomOverlayTokens
    {
        public static readonly ControlTokenIdentity Identity = new ControlTokenIdentity("AtomUI", "ShowCaseZoomOverlay");
    }

    public class ShowCaseZoomOverlayTokenResourceExtension : TokenResourceExtension<ShowCaseZoomOverlayTokenKey>
    {
        public ShowCaseZoomOverlayTokenResourceExtension()
        {
        }

        public ShowCaseZoomOverlayTokenResourceExtension(ShowCaseZoomOverlayTokenKey kind)
            : base(kind)
        {
        }

        protected override object GetResourceKey(ShowCaseZoomOverlayTokenKey kind)
        {
            var slot = (int)kind;
            if (slot >= 0)
            {
                if ((uint)slot >= 255u)
                {
                    throw new global::System.ArgumentOutOfRangeException(nameof(kind));
                }
                return ControlTokenResourceKey.Global(ShowCaseZoomOverlayTokens.Identity, (SharedTokenKind)slot);
            }
            var ownSlot = -1 - slot;
            if ((uint)ownSlot < 4u)
            {
                return (ShowCaseZoomOverlayTokenKind)ownSlot;
            }
            throw new global::System.ArgumentOutOfRangeException(nameof(kind));
        }
    }

